I18N.fa["pool.unlocked"] = "\u0642\u0641\u0644 IP \u062B\u0627\u0628\u062A \u0628\u0627\u0632 \u0634\u062F \u2014 \u06A9\u0627\u0646\u0641\u06CC\u06AF\u0647\u0627 \u062F\u0648\u0628\u0627\u0631\u0647 \u062A\u0635\u0627\u062F\u0641\u06CC \u0627\u0632 IP \u0647\u0627\u06CC \u062A\u0645\u06CC\u0632 \u0627\u0646\u062A\u062E\u0627\u0628 \u0645\u06CC\u0634\u0648\u0646\u062F";
I18N.fa["pool.note"] = "IP\u0647\u0627\u06CC \u0627\u06CC\u0646 \u0644\u06CC\u0633\u062A \u0627\u0632 \u0627\u0633\u06A9\u0646 \u0633\u0631\u0627\u0633\u0631\u06CC \u062C\u0645\u0639 \u0634\u062F\u0647\u0627\u0646\u062F \u0648 \u0639\u0645\u062F\u062A\u0627\u064B \u062F\u06CC\u062A\u0627\u0633\u0646\u062A\u0631 \u0647\u0633\u062A\u0646\u062F\u061B \u0628\u0631\u0627\u06CC \u0647\u0645\u06CC\u0646 \u0622\u062F\u0631\u0633\u0650 \u0627\u062A\u0635\u0627\u0644\u0650 \u06A9\u0627\u0646\u0641\u06CC\u06AF \u0647\u0645\u06CC\u0634\u0647 IP \u06A9\u0644\u0627\u062F\u0641\u0644\u0631 (\u2601\uFE0F) \u0645\u06CC\u0645\u0627\u0646\u062F \u062A\u0627 \u06A9\u0627\u0646\u0641\u06CC\u06AF \u0648\u0627\u0642\u0639\u0627\u064B \u0648\u0635\u0644 \u0634\u0648\u062F. \u0628\u0627 \u062F\u06A9\u0645\u0647\u0654 \xAB\u0633\u062A \u0628\u0647\u062A\u0631\u06CC\u0646 IP\u0647\u0627 \u0631\u0648\u06CC \u06A9\u0627\u0646\u0641\u06CC\u06AF\u0647\u0627\xBB \u067E\u0631\u0686\u0645 \u0648 \u0646\u0627\u0645 \u06A9\u0634\u0648\u0631 \u0631\u0648\u06CC \u0646\u0627\u0645 \u06A9\u0627\u0646\u0641\u06CC\u06AF \u0633\u062A \u0645\u06CC\u0634\u0648\u062F \u0648 \u0628\u0647\u062A\u0631\u06CC\u0646 IP\u0647\u0627\u06CC \u06A9\u0644\u0627\u062F\u0641\u0644\u0631\u0650 \u0646\u062A\u06CC\u062C\u0647 \u0647\u0645 \u0628\u0647 \u0644\u06CC\u0633\u062A IP \u062A\u0645\u06CC\u0632 \u0627\u0636\u0627\u0641\u0647 \u0645\u06CC\u0634\u0648\u0646\u062F. \u0628\u0631\u0627\u06CC IP \u062B\u0627\u0628\u062A\u0650 \u0648\u0635\u0644\u0634\u0648\u0646\u062F\u0647 \u0627\u0632 \xAB\u0627\u0633\u06A9\u0646\u0631 IP \u062A\u0645\u06CC\u0632\xBB \u067E\u0627\u06CC\u06CC\u0646 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646.";
I18N.fa["pool.running"] = "\u062F\u0631 \u062D\u0627\u0644 \u062A\u0633\u062A IP\u0647\u0627\u06CC \u06A9\u0634\u0648\u0631\u2026";
I18N.fa["pool.selCount"] = "IP";
I18N.fa["pool.eta"] = "\u0628\u0627\u0642\u06CC\u0645\u0627\u0646\u062F\u0647";
I18N.fa["pool.cfcount"] = "\u06A9\u0644\u0627\u062F\u0641\u0644\u0631";
I18N.fa["pool.bestms"] = "\u0628\u0647\u062A\u0631\u06CC\u0646 (ms)";
I18N.fa["pool.applied"] = "\u0631\u0648\u06CC \u06A9\u0627\u0646\u0641\u06CC\u06AF\u0647\u0627 \u0633\u062A \u0634\u062F";
I18N.fa["pool.appliedIps"] = "IP \u06AF\u0644\u0686\u06CC\u0646\u0634\u062F\u0647";
I18N.fa["pool.applying"] = "\u062F\u0631 \u062D\u0627\u0644 \u0633\u062A \u06A9\u0631\u062F\u0646\u2026";
I18N.fa["pool.appliedOk"] = "\u0628\u0647\u062A\u0631\u06CC\u0646 IP\u0647\u0627 \u0631\u0648\u06CC \u06A9\u0627\u0646\u0641\u06CC\u06AF\u0647\u0627 \u0633\u062A \u0634\u062F \u2713 \u2014 \u0646\u0627\u0645 \u06A9\u0627\u0646\u0641\u06CC\u06AF: {name}";
I18N.fa["pool.cleared"] = "\u0633\u062A \u06A9\u0634\u0648\u0631 \u0628\u0631\u062F\u0627\u0634\u062A\u0647 \u0634\u062F \u2014 \u06A9\u0627\u0646\u0641\u06CC\u06AF\u0647\u0627 \u0628\u0647 \u062D\u0627\u0644\u062A \u067E\u06CC\u0634\u0641\u0631\u0636 \u0628\u0631\u06AF\u0634\u062A\u0646\u062F";
I18N.fa["pool.needtest"] = "\u0627\u0648\u0644 \u062A\u0633\u062A \u0631\u0627 \u0627\u062C\u0631\u0627 \u06A9\u0646 \u062A\u0627 IP \u0633\u0627\u0644\u0645\u06CC \u0628\u0631\u0627\u06CC \u0633\u062A \u06A9\u0631\u062F\u0646 \u0628\u0627\u0634\u062F";
I18N.fa["pool.nocfApply"] = "\u2139\uFE0F \u0628\u06CC\u0646 \u0633\u0627\u0644\u0645\u0647\u0627 IP \u06A9\u0644\u0627\u062F\u0641\u0644\u0631\u06CC \u0646\u0628\u0648\u062F \u2014 \u067E\u0631\u0686\u0645 \u0648 \u0646\u0627\u0645 \u0631\u0648\u06CC \u06A9\u0627\u0646\u0641\u06CC\u06AF\u0647\u0627 \u0633\u062A \u0634\u062F \u0648 \u0622\u062F\u0631\u0633 \u0627\u062A\u0635\u0627\u0644 \u0647\u0645\u0686\u0646\u0627\u0646 IP \u062A\u0645\u06CC\u0632 \u06A9\u0644\u0627\u062F\u0641\u0644\u0631 \u0627\u0633\u062A";
I18N.fa["pool.of"] = "\u0627\u0632";
I18N.fa["pool.country"] = "\u06A9\u0634\u0648\u0631";

I18N.en["pool.title"] = "Proxy IP Pool";
I18N.en["pool.sub"] = "Auto-test & pick the best IP of a country";
I18N.en["pool.desc"] = "Pick a country and the system auto-tests its IPs and selects the best ones. Then tap \u201CSet best IPs on configs\u201D \u2014 the config name gets the country flag and the best IPs are applied to the configs.";
I18N.en["pool.search"] = "Search country";
